import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
import io
import os

# Set style
sns.set_theme(style="whitegrid")

def df_to_base64_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    image_base64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return image_base64

# 1. Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Data processing
total_books = len(df)
genre_counts = df['Genre'].value_counts()
avg_price = df['Price'].mean()
avg_rating = df['User Rating'].mean()
avg_reviews = df['Reviews'].mean()

# Price-Rating Correlation
correlation = df['Price'].corr(df['User Rating'])

# Genre Comparison
genre_stats = df.groupby('Genre')[['Price', 'User Rating', 'Reviews']].mean().round(2)

# Top Authors
author_counts = df['Author'].value_counts().head(10)
top_authors_stats = df[df['Author'].isin(author_counts.index)].groupby('Author').agg(
    Appearances=('Name', 'count'),
    Avg_Price=('Price', 'mean'),
    Avg_Rating=('User Rating', 'mean')
).sort_values(by='Appearances', ascending=False).round(2)

# Temporal Trends
yearly_trends = df.groupby(['Year', 'Genre'])[['Price', 'User Rating']].mean().reset_index()

# ---- Visualizations ----

# 1. Price vs Rating Scatter
fig, ax = plt.subplots(figsize=(8, 6))
sns.scatterplot(data=df, x='Price', y='User Rating', hue='Genre', alpha=0.6, ax=ax)
ax.set_title("Price vs. User Rating", fontsize=14)
ax.set_xlabel("Price ($)")
ax.set_ylabel("User Rating")
scatter_b64 = df_to_base64_image(fig)

# 2. Genre Comparison Bar Charts
fig, axes = plt.subplots(1, 3, figsize=(15, 5))
sns.barplot(data=df, x='Genre', y='Price', ax=axes[0], errorbar=None, palette='muted')
axes[0].set_title('Average Price by Genre')
sns.barplot(data=df, x='Genre', y='User Rating', ax=axes[1], errorbar=None, palette='muted')
axes[1].set_title('Average Rating by Genre')
axes[1].set_ylim(4.0, 5.0) # Ratings are tight
sns.barplot(data=df, x='Genre', y='Reviews', ax=axes[2], errorbar=None, palette='muted')
axes[2].set_title('Average Reviews by Genre')
genre_b64 = df_to_base64_image(fig)

# 3. Temporal Trends
fig, axes = plt.subplots(2, 1, figsize=(10, 10), sharex=True)
sns.lineplot(data=yearly_trends, x='Year', y='Price', hue='Genre', marker='o', ax=axes[0])
axes[0].set_title('Year-over-Year Average Price Trend')
axes[0].set_ylabel('Average Price ($)')
axes[0].set_xticks(range(2009, 2020))

sns.lineplot(data=yearly_trends, x='Year', y='User Rating', hue='Genre', marker='o', ax=axes[1])
axes[1].set_title('Year-over-Year Average Rating Trend')
axes[1].set_ylabel('Average Rating')
axes[1].set_xlabel('Year')
trend_b64 = df_to_base64_image(fig)

# Generate table rows for top authors
top_authors_rows = ""
for row in top_authors_stats.itertuples():
    top_authors_rows += f"<tr><td>{row.Index}</td><td>{row.Appearances}</td><td>${row.Avg_Price:.2f}</td><td>{row.Avg_Rating:.2f}</td></tr>\n"

# ---- HTML Generation ----
