            margin-top: 30px;
            border-bottom: 1px solid #ddd;
            padding-bottom: 5px;
        }}
        .kpi-container {{
            display: flex;
            justify-content: space-between;
            background-color: #ecf0f1;
            padding: 20px;
            border-radius: 6px;
            margin-bottom: 30px;
        }}
        .kpi {{
            text-align: center;
        }}
        .kpi .value {{
            font-size: 24px;
            font-weight: bold;
            color: #2980b9;
        }}
        .kpi .label {{
            font-size: 14px;
            color: #7f8c8d;
        }}
